package dev.raven.backup;
import android.app.*;import android.app.job.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.util.*;
/** Real, unforced one-shot Android job with disposable data and exact-created-archive cleanup. Refuses to replace an enabled owner schedule. */
public final class EncryptedScheduleTest extends Instrumentation {
 static final int JOB=718038;
 void require(boolean b,String why){if(!b)throw new AssertionError(why);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();LiveRestore live=new LiveRestore(c);BackupEngine e=live.engine;SharedPreferences p=RestorePreferences.prefs(c),s=BackupSchedule.prefs(c);require(!OperationService.running()&&!ScheduledBackupService.running&&!live.pointer.exists(),"Active operation");require(!s.getBoolean("enabled",false),"Enabled owner schedule; test will not replace it");require(!PasswordVault.remembered(c)&&!SetupCheck.installed(e),"Existing password/helper; test will not replace it");Map<String,?> oldP=p.getAll(),oldS=s.getAll(),oldReceipts=c.getSharedPreferences("archive-verification",0).getAll();File own=e.job(),apk=new File(own,"helper.apk");Uri folder=null;List<BackupCatalog.Entry> owned=new ArrayList<>();Uri tree=SetupActivity.folder(c);long started=System.currentTimeMillis();boolean installed=false;JobScheduler scheduler=c.getSystemService(JobScheduler.class);char[] password="scheduled-disposable-password".toCharArray();try{
  require(tree!=null,"Backup folder");try(InputStream in=c.getAssets().open("restore-check.apk");OutputStream out=new FileOutputStream(apk)){BackupEngine.copy(in,out,16*1024*1024);}e.run(e.job(),"pm install --user 0 "+BackupEngine.q(apk.getPath())+"\n",false);installed=true;SetupCheck.mode(e,"seed");
  SharedPreferences.Editor options=p.edit().putBoolean(ArchiveVerifier.ENCRYPT,true).putBoolean(ArchiveVerifier.VERIFY,true).putInt(ArchiveVerifier.RETENTION,0);for(String key:ExternalScopes.KEYS)options.putBoolean(key,false);options.commit();boolean refused=false;try{BackupSchedule.enable(c,Collections.singletonList(SetupCheck.PACKAGE),tree,1,false,false);}catch(IOException expected){refused=expected.getMessage().contains("Remember password");}require(refused&&!s.getBoolean("enabled",false),"Missing saved password scheduled anyway");PasswordVault.save(c,password,true);
  Uri scheduleTree=tree;JSONObject config=new JSONObject().put("packages",new JSONArray().put(SetupCheck.PACKAGE)).put("tree",scheduleTree.toString()).put("days",1).put("charging",false).put("idle",false);s.edit().putBoolean("enabled",true).putString("config",config.toString()).remove("lastRun").commit();require(scheduler.getPendingJob(JOB)==null,"Test job ID already present");require(scheduler.schedule(new JobInfo.Builder(JOB,new ComponentName(c,ScheduledBackupService.class)).setMinimumLatency(1000).setOverrideDeadline(5000).build())==JobScheduler.RESULT_SUCCESS,"Schedule rejected");long end=SystemClock.elapsedRealtime()+120000;while(SystemClock.elapsedRealtime()<end&&s.getLong("lastRun",0)==0)Thread.sleep(250);require(s.getLong("lastRun",0)>0&&!ScheduledBackupService.running,"Job did not finish");String report=s.getString("lastResult","");require(report.startsWith("Backed up 1 apps"),report);List<BackupCatalog.Entry> entries=new ArrayList<>();BackupCatalog.scan(c,tree,DocumentsContract.getTreeDocumentId(tree),0,new HashSet<>(),entries);BackupCatalog.read(c,entries);for(BackupCatalog.Entry entry:entries)if(entry.manifest!=null&&entry.manifest.optLong("created")>=started&&entry.manifest.getJSONArray("apps").length()==1&&entry.manifest.getJSONArray("apps").getJSONObject(0).getString("package").equals(SetupCheck.PACKAGE))owned.add(entry);entries=owned;require(entries.size()==1&&entries.get(0).encrypted&&entries.get(0).manifest!=null&&entries.get(0).verifiedAt>0,"Scheduled output not encrypted/verified: count="+entries.size()+" report="+report);SetupCheck.mode(e,"mutate");live.testing=true;live.restore(live.prepare(entries.get(0).uri),false,false);live.verifyLaunch(Collections.singletonList(SetupCheck.PACKAGE),false);result.putString("result","PASS encrypted schedule refused without saved password; real Android one-shot job ran without force, used remembered password, produced verified encrypted archive and restored disposable app data/metadata with independent app reads");
 }finally{scheduler.cancel(JOB);long end=SystemClock.elapsedRealtime()+30000;while(ScheduledBackupService.running&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);if(!ScheduledBackupService.running){SettingsTransfer.restore(p,oldP);SettingsTransfer.restore(s,oldS);SettingsTransfer.restore(c.getSharedPreferences("archive-verification",0),oldReceipts);if(!live.pointer.exists()){if(!owned.isEmpty())BackupStorage.delete(c,tree,owned);if(installed)e.run(e.job(),"pm uninstall "+BackupEngine.q(SetupCheck.PACKAGE)+"\n",false);if(folder!=null)DocumentsContract.deleteDocument(c.getContentResolver(),folder);e.clean(own);}Thread.sleep(300);ArchiveAccess.lock();PasswordVault.forget(c);}Arrays.fill(password,'\0');}finish(-1,result);
 }catch(Throwable t){result.putString("error",android.util.Log.getStackTraceString(t));finish(0,result);}}
}
